-- Supplier price list table: Eleganz LED lighting
CREATE TABLE IF NOT EXISTS supplier_price_items (
  id         SERIAL PRIMARY KEY,
  supplier   TEXT NOT NULL DEFAULT 'eleganz',
  category   TEXT NOT NULL,
  name       TEXT NOT NULL,
  article    TEXT,
  price_usd  NUMERIC(10,4),
  price_rub  NUMERIC(10,2),
  currency   TEXT NOT NULL DEFAULT 'USD',
  unit       TEXT NOT NULL DEFAULT 'шт',
  notes      TEXT,
  active     BOOLEAN DEFAULT true,
  sort_order INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE supplier_price_items ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Auth read price items"
  ON supplier_price_items FOR SELECT TO authenticated USING (true);

CREATE POLICY "Auth manage price items"
  ON supplier_price_items FOR ALL TO authenticated USING (true) WITH CHECK (true);

